#include <cstdio>
using namespace std;

static vector<long long> expected_out(const vector<long long>& a, long long k) {
    long long mx = a[0], mn = a[0];
    for (size_t i = 0; i < a.size(); i++) { mx = max(mx, a[i]); mn = min(mn, a[i]); }
    vector<long long> r = a;
    for (size_t i = 0; i < r.size(); i++) {
        if (r[i] > k) r[i] = mx;
        else if (r[i] < k) r[i] = mn;
    }
    return r;
}

static bool run_case(const string& exe, int cid, const string& input,
                     const vector<long long>& want, int& passed, int total) {
    string inf = "a12in_" + to_string(cid) + ".txt";
    string outf = "a12out_" + to_string(cid) + ".txt";
    { ofstream ofs(inf); ofs << input; }
    string cmd = "\"" + exe + "\" < " + inf + " > " + outf + " 2>/dev/null";
    int rc = system(cmd.c_str());
    if (rc != 0) { printf("[FAIL] case %d: program exit code %d\n", cid, rc); return false; }
    ifstream ifs(outf);
    vector<long long> got; long long v;
    while (ifs >> v) got.push_back(v);
    if (got != want) {
        printf("[FAIL] case %d: wrong output\n", cid);
        printf("  want: "); for (size_t i = 0; i < want.size(); i++) printf("%lld ", want[i]); printf("\n");
        printf("  got : "); for (size_t i = 0; i < got.size(); i++) printf("%lld ", got[i]); printf("\n");
        return false;
    }
    passed++;
    return true;
}

int main(int argc, char** argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s <candidate-exe>\n", argv[0]); return 2; }
    string exe = argv[1];
    int passed = 0, total = 0;
    auto check = [&](const string& input, long long k, const vector<long long>& a) {
        total++;
        int cid = total;
        run_case(exe, cid, input, expected_out(a, k), passed, total);
    };
    // case 1: PDF 样例
    check("5 0\n-2 -1 0 1 2\n", 0, {-2, -1, 0, 1, 2});
    // case 2: n=1 边界
    check("1 5\n5\n", 5, {5});
    // case 3: 全部等于 k
    check("4 3\n3 3 3 3\n", 3, {3, 3, 3, 3});
    // case 4: 有大于有小于
    check("3 4\n5 1 9\n", 4, {5, 1, 9});
    // case 5: 全为负数且 k 为负
    check("4 -3\n-100000 -3 -2 -1\n", -3, {-100000, -3, -2, -1});
    // case 6: 绝对值边界
    check("3 0\n-100000 0 100000\n", 0, {-100000, 0, 100000});
    // case 7~10: 随机
    srand(20241201);
    for (int t = 0; t < 4; t++) {
        int n = 1 + rand() % 500;
        long long k = rand() % 200001 - 100000;
        vector<long long> a(n);
        ostringstream os;
        os << n << " " << k << "\n";
        for (int i = 0; i < n; i++) { a[i] = rand() % 200001 - 100000; os << a[i] << (i + 1 < n ? ' ' : '\n'); }
        check(os.str(), k, a);
    }
    // case 11: 规模压测 n=100000
    {
        int n = 100000;
        long long k = 12345;
        vector<long long> a(n);
        ostringstream os;
        os << n << " " << k << "\n";
        for (int i = 0; i < n; i++) { a[i] = rand() % 200001 - 100000; os << a[i] << (i + 1 < n ? ' ' : '\n'); }
        check(os.str(), k, a);
    }
    printf("Results: %d/%d passed\n", passed, total);
    return passed == total ? 0 : 1;
}

