#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <cstdlib>
#include <cstdio>
using namespace std;

static string block(char d, int row) {
    if (d == '0') {
        if (row == 0 || row == 4) return ".....";
        if (row == 2) return "****.";
        return ".***.";
    }
    if (d == '1') return "****.";
    if (d == '2') {
        if (row == 0) return ".....";
        if (row == 1) return "****.";
        if (row == 2) return ".....";
        if (row == 3) return ".****";
        return ".....";
    }
    // d == '3'
    if (row == 0) return ".....";
    if (row == 1) return "****.";
    if (row == 2) return ".....";
    if (row == 3) return "****.";
    return ".....";
}

static vector<string> expected_out(const string& n) {
    vector<string> lines;
    for (int row = 0; row < 5; row++) {
        string line;
        for (char d : n) line += block(d, row);
        lines.push_back(line);
    }
    return lines;
}

static string trim_right(const string& s) {
    size_t e = s.size();
    while (e > 0 && (s[e - 1] == ' ' || s[e - 1] == '\t' || s[e - 1] == '\r')) e--;
    return s.substr(0, e);
}

int main(int argc, char** argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s <candidate-exe>\n", argv[0]); return 2; }
    string exe = argv[1];
    int passed = 0, total = 0;
    auto check = [&](const string& n) {
        total++;
        int cid = total;
        string inf = "a12p2in_" + to_string(cid) + ".txt";
        string outf = "a12p2out_" + to_string(cid) + ".txt";
        { ofstream ofs(inf); ofs << n << "\n"; }
        string cmd = "\"" + exe + "\" < " + inf + " > " + outf + " 2>/dev/null";
        int rc = system(cmd.c_str());
        if (rc != 0) { printf("[FAIL] case %d: program exit code %d\n", cid, rc); return; }
        vector<string> want = expected_out(n);
        ifstream ifs(outf);
        vector<string> got; string line;
        while (getline(ifs, line)) got.push_back(trim_right(line));
        while (!got.empty() && got.back().empty()) got.pop_back();
        if (got != want) {
            printf("[FAIL] case %d (n=%s): wrong output\n", cid, n.size() <= 24 ? n.c_str() : "<long>");
            for (size_t i = 0; i < want.size(); i++)
                printf("  want[%d]: %s\n", (int)i, i < got.size() ? (got[i] == want[i] ? "(same)" : want[i].c_str()) : "<missing>");
            for (size_t i = 0; i < got.size(); i++) printf("  got [%d]: %s\n", (int)i, got[i].c_str());
            return;
        }
        passed++;
    };
    check("12230");   // PDF 样例
    check("0");
    check("1");
    check("2");
    check("3");
    check("3210");
    check("0123");
    check("3333333333");
    srand(20241202);
    for (int t = 0; t < 4; t++) {
        int len = 1 + rand() % 60;
        string n;
        for (int i = 0; i < len; i++) n += (char)('0' + rand() % 4);
        check(n);
    }
    {   // 规模压测：100000 位
        string n(100000, '0');
        for (size_t i = 0; i < n.size(); i++) n[i] = (char)('0' + rand() % 4);
        check(n);
    }
    printf("Results: %d/%d passed\n", passed, total);
    return passed == total ? 0 : 1;
}
